import json
import math
import numpy as np

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'stereo-course/merzlyak-10-base/lessons'
OUT.mkdir(parents=True, exist_ok=True)
WRITTEN = []

def vec(x): return np.array(x, dtype=float)
def lerp(a,b,t): return ((1-t)*vec(a)+t*vec(b)).tolist()
def addpoint(m,name,p): m['points'][name]=[round(float(v),9) for v in p]; return name
def at(m,name,a,b,t): return addpoint(m,name,lerp(m['points'][a],m['points'][b],t))
def line_hit(m,name,a,b,c,d):
    A,B,C,D=(vec(m['points'][x]) for x in (a,b,c,d))
    mat=np.column_stack((B-A,-(D-C)))
    ts,res,rank,_=np.linalg.lstsq(mat,C-A,rcond=None)
    assert rank==2 and np.linalg.norm(A+ts[0]*(B-A)-C-ts[1]*(D-C))<1e-7,(name,a,b,c,d)
    return addpoint(m,name,A+ts[0]*(B-A))
def model(points,edges,faces=(),labels=None,planar=False):
    return {'points':deepcopy(points),'edges':[list(e) for e in edges],'faces':[list(f) for f in faces],
      'labelNames':list(points)[:8] if labels is None else labels,
      'views':{'neutral':{'label':'Исходная конфигурация. Найдите данные точки и грани.'}},'planar':planar}
def cube():
    P={'A':[-1,-1,0],'B':[-1,1,0],'C':[1,1,0],'D':[1,-1,0],
       'A1':[-1,-1,2],'B1':[-1,1,2],'C1':[1,1,2],'D1':[1,-1,2]}
    F=[['A','B','C','D'],['A1','B1','C1','D1'],['A','B','B1','A1'],['B','C','C1','B1'],['C','D','D1','C1'],['D','A','A1','D1']]
    E=[['A','B'],['B','C'],['C','D'],['D','A'],['A1','B1'],['B1','C1'],['C1','D1'],['D1','A1'],['A','A1'],['B','B1'],['C','C1'],['D','D1']]
    return model(P,E,F)
def tetra(apex='S'):
    P={'A':[-2,-1,0],'B':[0,2,0],'C':[2,-1,0],apex:[0,0,3]}
    E=[['A','B'],['B','C'],['C','A'],['A',apex],['B',apex],['C',apex]]
    F=[['A','B','C'],['A','B',apex],['B','C',apex],['C','A',apex]]
    return model(P,E,F)
def pyramid(apex='S',pentagon=False):
    P={'A':[-2,-1,0],'B':[-1,1,0],'C':[1,1,0],'D':[1.8,-1,0],apex:[0,0,3]}
    base=['A','B','C','D']
    if pentagon:
        P={'A':[-2,-.5,0],'B':[-1,1,0],'C':[1,1,0],'D':[2,-.5,0],'E':[0,-2,0],apex:[0,0,3]}
        base=['A','B','C','D','E']
    E=[[base[i],base[(i+1)%len(base)]] for i in range(len(base))]+[[a,apex] for a in base]
    F=[base]+[[base[i],base[(i+1)%len(base)],apex] for i in range(len(base))]
    return model(P,E,F)
def prism(tri=True):
    base={'A':[-2,-1,0],'B':[0,2,0],'C':[2,-1,0]} if tri else {'A':[-2,-1,0],'B':[-1,1,0],'C':[1,1,0],'D':[1.8,-1,0]}
    names=list(base);P=deepcopy(base)
    for n in names: P[n+'1']=lerp(P[n],vec(P[n])+[.45,.2,3],1)
    E=[[n,n+'1'] for n in names]
    F=[names,[n+'1' for n in names]]
    for i,a in enumerate(names):
        b=names[(i+1)%len(names)];E.extend([[a,b],[a+'1',b+'1']]);F.append([a,b,b+'1',a+'1'])
    return model(P,E,F)
def view(m,key,label,segments=(),polygon=(),points=()):
    v={'label':label}
    if segments:v['segments']=[list(x) for x in segments]
    if polygon:v['polygon']=list(polygon)
    if points:v['points']=list(points)
    m['views'][key]=v
    return key
def section(m,three,naming):
    a,b,c=(vec(m['points'][x]) for x in three);normal=np.cross(b-a,c-a)
    assert np.linalg.norm(normal)>1e-8
    names=[]
    for u,v in m['edges']:
        x,y=vec(m['points'][u]),vec(m['points'][v]);sx,sy=np.dot(normal,x-a),np.dot(normal,y-a)
        hits=[]
        if abs(sx)<1e-8:hits.append((u,x))
        if abs(sy)<1e-8:hits.append((v,y))
        if sx*sy < -1e-10:
            p=x+(y-x)*sx/(sx-sy)
            found=next((n for n,q in m['points'].items() if np.linalg.norm(vec(q)-p)<1e-7),None)
            name=found or naming.get(frozenset([u,v]))
            assert name,('missing-section-name',u,v,p)
            if not found:addpoint(m,name,p)
            hits.append((name,p))
        for name,p in hits:
            if name not in names:names.append(name)
    center=sum((vec(m['points'][n]) for n in names))/len(names)
    axis=vec(m['points'][names[0]])-center;axis/=np.linalg.norm(axis)
    norm=normal/np.linalg.norm(normal);other=np.cross(norm,axis)
    names.sort(key=lambda n:math.atan2(np.dot(vec(m['points'][n])-center,other),np.dot(vec(m['points'][n])-center,axis)))
    view(m,'section','Построенное сечение: '+''.join(names),polygon=names)
    return names
def J(text,kind='theorem'):return {'kind':kind,'text':text}
COMMON='Две общие точки определяют прямую пересечения двух различных плоскостей. В каждой грани сечение идёт по прямой.'
def step(title,prompt,text,v=None,why=COMMON):
    s={'title':title,'prompt':prompt,'explanation':text,'justifications':[J(why)]}
    if v:s['view']=v
    return s
def save(n,title,statement,goal,m,steps,*,sub=None,pages=None,helptext=None,answer=None,caption=None):
    if pages is None: pages=[21 if n==1 else 22 if n<=12 else 23 if n<=14 else 24 if n<=21 else 25 if n<=27 else 26]
    id=f'ex-03-{n:03d}'+('-'+sub[0] if sub else '')
    src={'bookId':'merzlyak-2022-10-base','collection':'main','printedPages':pages,'pdfPages':[p+1 for p in pages],'chapter':'Глава 1. Введение в стереометрию','exercise':f'3.{n}'}
    if sub:src['subpart']=sub[1]
    for i,s in enumerate(steps,1):s['id']=f'step-{i}'
    # Existing viewer adds the focused points of a view. Keep unrelated labels
    # off later construction steps; show the original names only in neutral.
    neutral_names=m.get('labelNames',[])
    m['labelNames']=[]
    if neutral_names:m['views']['neutral']['points']=neutral_names
    l={'schemaVersion':1,'revision':1,'id':id,'kind':'exercise','title':f'3.{n}'+(sub[1] if sub else '')+'. '+title,'status':'draft','source':src,
       'statement':{'text':statement,'goal':goal},
       'visualization':{'type':'scene3d','caption':caption or 'Схематическая модель сохраняет принадлежность точек прямым и граням. Размеры выбраны для наглядности; измерять по рисунку не нужно. Прямые можно продолжать за пределы изображённых отрезков.','model':m},
       'help':[{'id':'help-1','question':'С чего начать?','text':helptext or 'Найдите две точки, которые лежат в одной грани и в искомой плоскости. Соедините их; при необходимости продолжите прямую до ребра или его продолжения.'}],
       'steps':steps,'answer':answer or {'mode':'manual','prompt':'Запишите ответ или выполните построение и обоснуйте каждый шаг. Запись предназначена для обсуждения с учителем; доказательство автоматически не оценивается.'},
       'review':{'source':'pending','mathematics':'pending','pedagogy':'pending'}}
    (OUT/(id+'.json')).write_text(json.dumps(l,ensure_ascii=False,indent=2)+'\n')
    WRITTEN.append(id)

